function esc(value) {
  return String(value ?? "").replace(/[&<>'"]/g, (char) => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[char]);
}

function number(value, digits = 2) {
  return value == null || Number.isNaN(Number(value)) ? "unknown" : Number(value).toFixed(digits);
}

function clamp(value, low, high) {
  return Math.max(low, Math.min(high, value));
}

async function unpackDepictions(packed) {
  if (!packed || packed.encoding !== "gzip+base64") throw new Error("Unsupported depiction encoding");
  const entries = await Promise.all(Object.entries(packed.items).map(async ([id, encoded]) => {
    const binary = atob(encoded);
    const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    return [id, await new Response(stream).text()];
  }));
  return Object.fromEntries(entries);
}

export default {
  async render({ model, el }) {
    const root = document.createElement("section");
    root.className = "mel";
    root.dataset.testid = "molecule-evidence-lens";
    el.replaceChildren(root);
    const rawData = model.get("payload");
    const data = {...rawData, depictions: await unpackDepictions(rawData.depictions)};
    const records = data.evidence_records;
    const nominations = data.nominations;
    const predictions = new Map();
    for (const row of nominations.predictions) {
      predictions.set(`${row.fit_key}|${row.molecule_id}`, row);
    }
    let animationFrame = null;
    let fitDebounce = null;
    let previousStage = (model.get("state") || {}).evidence_stage;

    const getState = () => model.get("state") || {};
    const setState = (patch) => {
      const current = getState();
      const next = {...current, ...patch, event_sequence: (current.event_sequence || 0) + 1};
      model.set("state", next);
      model.save_changes();
    };
    const stageIndex = (state) => {
      if (state.returned_to_proposal) return 8;
      if (state.caco_revealed) return 7;
      if (state.measurements_revealed) return 6;
      if (state.selection_kind) return 5;
      if (state.fit_explored) return 4;
      if (state.candidate_id) return 3;
      return state.seed_id ? 2 : 1;
    };
    const progress = (state) => Array.from({length: 9}, (_, index) => `<span data-done="${index < stageIndex(state)}"></span>`).join("");
    const depiction = (id) => data.depictions[id] || "";
    const candidateList = (seedId) => data.candidates.filter((candidate) => candidate.seed_id === seedId);
    const candidateRecord = (state) => state.candidate_id ? records[state.candidate_id] : null;
    const committedIds = (state) => {
      if (state.selection_kind === "active_fit") return nominations.nominations[state.committed_fit_key] || [];
      if (state.selection_kind === "ensemble") return nominations.ensemble_ids;
      return [];
    };
    const sourceLabel = (state) => {
      if (state.selection_kind === "ensemble") return "Ensemble shortlist";
      const meta = nominations.fit_metadata.find((item) => item.fit_key === state.committed_fit_key);
      return meta ? `${meta.label} shortlist` : "Saved-fit shortlist";
    };
    const committedInspection = (state) => {
      const ids = committedIds(state);
      return ids.includes(state.inspected_molecule_id) ? state.inspected_molecule_id : ids[0];
    };
    const storyHeader = (state) => {
      if (!state.candidate_id) return {
        eyebrow: "Choose an example to carry",
        title: "Pick a starting point—and know what the choice changes.",
        lede: "A measured seed filters the cached generation examples. The proposal you retain will return at the end; neither choice changes the separate retrospective shortlist analysis.",
      };
      if (state.returned_to_proposal) return {
        eyebrow: "Apply what the measurements taught us",
        title: "What would we measure on the proposal next?",
        lede: "The generated structure is still only a proposal. The retrospective results help frame a better question; they do not supply this molecule with experimental evidence.",
      };
      if (state.caco_revealed) return {
        eyebrow: "Widen the evidence",
        title: "What important question is still unanswered?",
        lede: "The same committed fifty now gains a separate view of permeability and efflux. Missing evidence stays missing rather than becoming failure.",
      };
      if (state.measurements_revealed) return {
        eyebrow: "Prediction meets experiment",
        title: "What changed when we inspected the measurements?",
        lede: "The same fifty molecules move from predicted to measured properties. The shortlist can remain useful even when individual recommendations surprise us.",
      };
      if (state.selection_kind) return {
        eyebrow: "Keep the shortlist fixed",
        title: "What did the chosen model expect?",
        lede: "These exact fifty IDs are now committed. Their experimental outcomes remain hidden until you choose to compare prediction with measurement.",
      };
      return {
        eyebrow: "Spend the illustrative fifty-experiment budget",
        title: "How sensitive is the shortlist to the fitted model?",
        lede: "Each saved fit ranks the same held-out molecules after a different training fold. Move between fits to see whether the same candidates keep receiving attention.",
      };
    };

    function choiceCard(id, meta, selected, kind) {
      return `<button type="button" class="mel__choice" data-${kind}-id="${esc(id)}" aria-pressed="${selected}">
        <span class="mel__choice-image">${depiction(id)}</span>
        <span><strong>${esc(id)}</strong><small>${esc(meta)}</small></span>
      </button>`;
    }

    function selectionMarkup(state) {
      const seeds = data.seeds.map((seed) => choiceCard(
        seed.seed_id,
        `Measured LogD ${number(seed.measured_LogD, 1)} · KSOL ${number(seed.measured_KSOL_uM, 0)} µM`,
        state.seed_id === seed.seed_id,
        "seed",
      )).join("");
      const available = candidateList(state.seed_id);
      const first = available.slice(0, 4);
      if (state.candidate_id && !first.some((row) => row.candidate_id === state.candidate_id)) {
        first.push(available.find((row) => row.candidate_id === state.candidate_id));
      }
      const firstIds = new Set(first.filter(Boolean).map((row) => row.candidate_id));
      const cards = first.filter(Boolean).map((candidate) => choiceCard(
        candidate.candidate_id,
        `seed similarity ${number(candidate.similarity_to_seed)} · experiments unknown`,
        state.candidate_id === candidate.candidate_id,
        "candidate",
      )).join("");
      const extras = available.filter((row) => !firstIds.has(row.candidate_id));
      const extraMarkup = extras.length ? `<details class="mel__extra"><summary>Inspect ${extras.length} more recorded proposals</summary><div class="mel__cards">${extras.map((candidate) => choiceCard(candidate.candidate_id, `seed similarity ${number(candidate.similarity_to_seed)}`, state.candidate_id === candidate.candidate_id, "candidate")).join("")}</div></details>` : "";
      return `<div class="mel__transition"><p class="mel__eyebrow">From measured evidence to an unmeasured idea</p><h3>Choose one example to remember while we test the selection process.</h3><p>First choose a real measured training molecule. That choice only changes which cached ChemLlama outputs appear beside it. Then retain one generated proposal to revisit after the retrospective investigation; it does not influence which fifty held-out molecules the models select.</p></div>
      <div class="mel__selection">
        <div class="mel__panel"><p class="mel__eyebrow">Choose a measured reference</p><p class="mel__muted">The cards show measured LogD and kinetic solubility. Your choice filters the recorded generation examples below; it does not change the model comparison.</p><div class="mel__cards">${seeds}</div></div>
        <div class="mel__panel"><p class="mel__eyebrow">Retain one unmeasured proposal</p><p class="mel__muted">These are chemically screened, cached generation outputs. Choose a structure to carry to the ending. Its experiments remain unknown.</p>${cards ? `<div class="mel__cards">${cards}</div>${extraMarkup}` : `<p class="mel__muted">Choose a measured reference to see its associated proposals.</p>`}</div>
      </div>`;
    }

    function retainedMarkup(state) {
      const candidate = candidateRecord(state);
      if (!candidate) return `<div class="mel__retained"><span>No generated proposal retained yet</span><span>Choosing a card keeps that exact candidate separate from retrospective molecules.</span></div>`;
      return `<div class="mel__retained" data-testid="retained-candidate"><span>Retained proposal · <strong>${esc(candidate.molecule_id)}</strong> from seed ${esc(candidate.seed_id)}</span><span>Computed structure context only · experimental profile unknown</span></div>`;
    }

    function selectionShell(state) {
      if (!state.candidate_id) return selectionMarkup(state);
      return `<details class="mel__change"><summary>Change the example carried through the story · current ${esc(state.candidate_id)}</summary>${selectionMarkup(state)}</details>`;
    }

    function endpointDisplay(record, stage, endpoint, index) {
      if (record.role === "generated_proposal") return {status: "missing", text: "unknown"};
      if (stage === "nomination" || stage === "prediction") {
        if (index < 2) return {status: "predicted", text: "predicted"};
        return {status: "hidden", text: "not shown"};
      }
      if (stage === "measured" && index > 1) return {status: "hidden", text: "not shown"};
      return {status: endpoint.status, text: endpoint.bound || (endpoint.value == null ? endpoint.status : `${number(endpoint.value, endpoint.value >= 100 ? 1 : 2)} ${endpoint.unit}`)};
    }

    function evidenceCard(id, state, fitKey = state.active_fit_key) {
      const record = records[id];
      if (!record) return `<div class="mel__panel"><p>Unknown record ${esc(id)}</p></div>`;
      const stage = state.returned_to_proposal ? "returned" : state.evidence_stage;
      const fitPrediction = predictions.get(`${fitKey}|${id}`);
      const ensemble = record.ensemble_prediction;
      const measurement = record.measurement_summary;
      const slots = record.endpoints.map((endpoint, index) => {
        const shown = endpointDisplay(record, stage, endpoint, index);
        return `<span class="mel__slot" data-status="${shown.status}" aria-label="${esc(endpoint.label)}: ${esc(shown.text)}">${esc(endpoint.short_label)}</span>`;
      }).join("");
      let values = "";
      if (record.role === "generated_proposal") {
        values = `<span><strong>Unknown</strong>experimental LogD</span><span><strong>Unknown</strong>experimental KSOL</span><span><strong>${esc(record.nearest_training_id)}</strong>nearest training context</span><span><strong>${number(record.nearest_training_similarity, 3)}</strong>Morgan similarity</span>`;
      } else if (stage === "nomination" && fitPrediction) {
        values = `<span><strong>${number(fitPrediction.pred_fit_LogD, 3)}</strong>fit-predicted LogD</span><span><strong>${number(fitPrediction.pred_fit_KSOL_uM, 1)} µM</strong>fit-predicted KSOL</span><span><strong>${data.nominations.inclusion_counts[id] || 0}/25</strong>fit nominations</span><span><strong>${esc(record.nearest_training_id)}</strong>training context</span>`;
      } else if (stage === "prediction" && ensemble) {
        values = `<span><strong>${number(ensemble.LogD, 3)}</strong>mean-predicted LogD</span><span><strong>${number(ensemble.KSOL_uM, 1)} µM</strong>mean-predicted KSOL</span><span><strong>${data.nominations.inclusion_counts[id] || 0}/25</strong>fit nominations</span><span><strong>${number(ensemble.score, 3)}</strong>illustrative score</span>`;
      } else if (measurement) {
        values = `<span><strong>${number(measurement.LogD, 2)}</strong>measured LogD</span><span><strong>${number(measurement.KSOL_uM, 1)} µM</strong>measured KSOL</span><span><strong>${measurement.target_pass ? "Meets" : "Misses"}</strong>two-property target</span><span><strong>${data.nominations.inclusion_counts[id] || 0}/25</strong>fit nominations</span>`;
        if (stage === "caco") {
          const papp = record.endpoints[4];
          const efflux = record.endpoints[5];
          values += `<span><strong>${papp.value == null ? esc(papp.bound || "unknown") : number(papp.value, 2)}</strong>Papp · ${esc(papp.unit)}</span><span><strong>${efflux.value == null ? esc(efflux.bound || "unknown") : number(efflux.value, 2)}</strong>efflux ratio</span>`;
        }
      }
      const badge = id === data.retrospective.unanimous_id ? "25/25 nomination—not certain success" : record.role.replaceAll("_", " ");
      return `<div class="mel__panel mel__card" data-testid="molecule-card">
        <div class="mel__structure">${depiction(id)}</div>
        <div class="mel__identity"><strong>${esc(id)}</strong><span class="mel__badge">${esc(badge)}</span></div>
        <div class="mel__strip">${slots}</div>
        <div class="mel__values">${values}</div>
        <p class="mel__muted" style="margin:10px 0 0">${esc(record.source)}</p>
      </div>`;
    }

    function trayMarkup(ids, state, stage) {
      return `<div class="mel__tray" aria-label="Committed fifty molecule tray">${ids.map((id) => {
        const record = records[id];
        const missingCaco = stage === "caco" && (record.endpoints[4].value == null || record.endpoints[5].value == null);
        const pass = stage !== "prediction" && record.measurement_summary && record.measurement_summary.target_pass;
        return `<button type="button" data-tray-id="${esc(id)}" data-pass="${Boolean(pass)}" data-missing="${missingCaco}" aria-pressed="${state.inspected_molecule_id === id}" aria-label="Inspect ${esc(id)}${missingCaco ? "; Caco-2 evidence missing or bounded" : ""}"></button>`;
      }).join("")}</div>`;
    }

    function nominationMarkup(state) {
      const fitIndex = clamp(Number(state.active_fit_index || 0), 0, nominations.fit_keys.length - 1);
      const fitKey = nominations.fit_keys[fitIndex];
      const active = new Set(nominations.nominations[fitKey]);
      const cells = nominations.union_order.map((id) => `<button type="button" class="mel__cell" data-union-id="${esc(id)}" data-nominated="${active.has(id)}" data-unanimous="${id === data.retrospective.unanimous_id}" aria-pressed="${state.inspected_molecule_id === id}" aria-label="${esc(id)}; nominated in ${data.nominations.inclusion_counts[id]} of 25 fits; ${active.has(id) ? "selected by active fit" : "not selected by active fit"}"></button>`).join("");
      const overlap = nominations.fit_to_ensemble_overlap[fitKey];
      return `<div class="mel__instrument">
        <div class="mel__panel mel__viewport">
          <div class="mel__toolbar">
            <div class="mel__fit"><div class="mel__fit-label"><strong>Compare the twenty-five saved model fits</strong><span data-fit-label>${esc(nominations.fit_metadata[fitIndex].label)}</span></div><input data-testid="fit-scrubber" type="range" min="0" max="24" step="1" value="${fitIndex}" aria-label="Compare saved model fits"></div>
            <div class="mel__stats"><span><strong>50</strong> nominated</span><span><strong data-overlap>${overlap}</strong> overlap ensemble</span><span><strong>${50 - overlap}</strong> active-only</span><span><strong>${50 - overlap}</strong> ensemble-only</span></div>
          </div>
          <div class="mel__matrix" data-matrix aria-label="Fixed-order nomination layout of 256 molecules">${cells}</div>
          <div class="mel__legend"><span><i class="mel__swatch mel__swatch--selected"></i>active fit nomination</span><span><i class="mel__swatch"></i>not nominated</span><span><i class="mel__swatch mel__swatch--unanimous"></i>unanimous nomination</span><span>Layout order: inclusion frequency descending, ensemble score descending, ID ascending; not chemical geometry.</span></div>
          ${trayMarkup(nominations.nominations[fitKey], state, "prediction")}
          <p class="mel__muted">Across all 25 saved repeat/fold fits: <strong>256 distinct nominations</strong>, <strong>1 unanimous record</strong>. These related fits share methods and overlapping training data; disagreement is selection sensitivity, not calibrated uncertainty.</p>
          <div class="mel__question"><strong>Which recommendation should receive the fifty experimental slots?</strong><span>Choose the active fit exactly as shown, or use the average prediction across fits. The chosen IDs remain fixed for the measurement reveal.</span></div>
          <div class="mel__action-row"><button type="button" class="mel__action" data-primary="true" data-action="commit-fit" ${state.fit_explored ? "" : "disabled"}>Choose this model’s fifty</button><button type="button" class="mel__action" data-action="commit-ensemble" ${state.fit_explored ? "" : "disabled"}>Choose the averaged-model fifty</button><button type="button" class="mel__action" data-action="focus-unanimous">Inspect the one 25/25 nominee</button></div>
          <p class="mel__muted">The active inspected molecule appears in <strong>${data.nominations.inclusion_counts[state.inspected_molecule_id] || 0}/25</strong> saved fits. Commitment preserves this exact ordered list even if you scrub later.</p>
        </div>
        <div data-card-host>${evidenceCard(state.inspected_molecule_id, state, fitKey)}</div>
      </div>`;
    }

    function plotGeometry(ids) {
      const xs = [];
      const ys = [];
      for (const id of ids) {
        const record = records[id];
        xs.push(record.ensemble_prediction.LogD, record.measurement_summary.LogD);
        ys.push(record.ensemble_prediction.KSOL_uM, record.measurement_summary.KSOL_uM);
      }
      const xMin = Math.floor((Math.min(...xs) - .2) * 2) / 2;
      const xMax = Math.ceil((Math.max(...xs) + .2) * 2) / 2;
      const lyMin = Math.log10(Math.min(...ys) * .8);
      const lyMax = Math.log10(Math.max(...ys) * 1.25);
      const box = {w: 720, h: 390, left: 62, right: 22, top: 20, bottom: 54};
      const x = (value) => box.left + (value - xMin) / (xMax - xMin) * (box.w - box.left - box.right);
      const y = (value) => box.top + (lyMax - Math.log10(value)) / (lyMax - lyMin) * (box.h - box.top - box.bottom);
      return {ids, xMin, xMax, lyMin, lyMax, box, x, y};
    }

    function propertyPlot(state) {
      const ids = committedIds(state);
      const geometry = plotGeometry(ids);
      const measured = state.evidence_stage !== "prediction";
      const {box, x, y} = geometry;
      const xTicks = Array.from({length: 6}, (_, index) => geometry.xMin + index * (geometry.xMax - geometry.xMin) / 5);
      const yTicks = [100, 200, 500, 1000].filter((tick) => Math.log10(tick) >= geometry.lyMin && Math.log10(tick) <= geometry.lyMax);
      const target = data.targets;
      const selected = committedInspection(state);
      const selectedRecord = records[selected];
      const connector = measured && selectedRecord ? `<line class="connector" x1="${x(selectedRecord.ensemble_prediction.LogD)}" y1="${y(selectedRecord.ensemble_prediction.KSOL_uM)}" x2="${x(selectedRecord.measurement_summary.LogD)}" y2="${y(selectedRecord.measurement_summary.KSOL_uM)}"></line>` : "";
      const points = geometry.ids.map((id) => {
        const record = records[id];
        const px = measured ? record.measurement_summary.LogD : record.ensemble_prediction.LogD;
        const py = measured ? record.measurement_summary.KSOL_uM : record.ensemble_prediction.KSOL_uM;
        return `<circle class="point" data-point-id="${esc(id)}" data-measured="${measured}" data-pass="${measured ? record.measurement_summary.target_pass : true}" data-selected="${id === selected}" cx="${x(px)}" cy="${y(py)}" r="${id === selected ? 7 : 5}" role="button" aria-label="Inspect ${esc(id)}: ${measured ? "measured" : "ensemble-predicted"} LogD ${number(px, 2)}, kinetic solubility ${number(py, 1)} micromolar"></circle>`;
      }).join("");
      return `<svg class="mel__plot" data-testid="property-plane" viewBox="0 0 ${box.w} ${box.h}" role="img" aria-label="The committed fifty in the LogD and kinetic-solubility property plane">
        <rect class="target" x="${x(target.logd_low)}" y="${box.top}" width="${x(target.logd_high) - x(target.logd_low)}" height="${y(target.ksol_min_um) - box.top}"></rect>
        ${xTicks.map((tick) => `<line class="axis" x1="${x(tick)}" y1="${box.top}" x2="${x(tick)}" y2="${box.h - box.bottom}"></line><text class="tick" x="${x(tick)}" y="${box.h - box.bottom + 18}" text-anchor="middle">${number(tick, 1)}</text>`).join("")}
        ${yTicks.map((tick) => `<line class="axis" x1="${box.left}" y1="${y(tick)}" x2="${box.w - box.right}" y2="${y(tick)}"></line><text class="tick" x="${box.left - 9}" y="${y(tick) + 4}" text-anchor="end">${tick}</text>`).join("")}
        <text class="axis-label" x="${(box.left + box.w - box.right) / 2}" y="${box.h - 13}" text-anchor="middle">${measured ? "Measured" : "Predicted"} LogD</text>
        <text class="axis-label" transform="translate(16 ${(box.top + box.h - box.bottom) / 2}) rotate(-90)" text-anchor="middle">${measured ? "Measured" : "Predicted"} KSOL (µM, log scale)</text>
        ${connector}${points}
      </svg>`;
    }

    function shortlistSummary(ids) {
      const passes = ids.filter((id) => records[id].measurement_summary.target_pass).length;
      return {passes, count: ids.length};
    }

    function randomBand(summary) {
      const ref = data.retrospective.random_reference;
      const x = (value) => 28 + value / 50 * 664;
      return `<svg class="mel__random" viewBox="0 0 720 52" role="img" aria-label="Random fifty 95 percent simulated range ${ref.random_low_95} to ${ref.random_high_95}; exact expected ${number(ref.random_expected_passes, 2)}; committed observed ${summary.passes}">
        <line x1="28" y1="25" x2="692" y2="25" stroke="var(--line)"></line>
        <rect class="band" x="${x(ref.random_low_95)}" y="15" width="${x(ref.random_high_95) - x(ref.random_low_95)}" height="20" rx="5"></rect>
        <line class="expected" x1="${x(ref.random_expected_passes)}" y1="10" x2="${x(ref.random_expected_passes)}" y2="40"></line>
        <line class="observed" x1="${x(summary.passes)}" y1="7" x2="${x(summary.passes)}" y2="43"></line>
        <text x="28" y="50">0 passes</text><text x="692" y="50" text-anchor="end">50 passes</text>
      </svg>`;
    }

    function outcomeMarkup(state) {
      const measured = state.evidence_stage !== "prediction";
      const ids = committedIds(state);
      const selected = committedInspection(state);
      const selectedRecord = records[selected];
      const summary = shortlistSummary(ids);
      const ref = data.retrospective.random_reference;
      return `<div class="mel__instrument">
        <div class="mel__panel mel__viewport">
          <div class="mel__toolbar"><div><p class="mel__eyebrow">${measured ? "Observed evidence" : "Predictions only"}</p><h3>${measured ? "The same fifty, now measured" : "The committed fifty, before measurement"}</h3><span class="mel__badge">${esc(sourceLabel(state))}</span></div>${measured ? `<button type="button" class="mel__action" data-action="replay">Replay predicted-to-measured movement</button>` : ""}</div>
          <div data-plot-host>${propertyPlot(state)}</div>
          ${trayMarkup(ids, {...state, inspected_molecule_id:selected}, state.evidence_stage)}
          ${state.selection_notice ? `<p class="mel__muted">${esc(state.selection_notice)}</p>` : ""}
          ${measured ? `<div class="mel__result"><div class="mel__metric"><strong>${summary.passes}/50</strong>committed shortlist measured target passes</div><div class="mel__metric"><strong>${data.retrospective.ensemble_target_passes}/50</strong>ensemble measured target passes</div><div class="mel__metric"><strong>${data.retrospective.fit_target_passes_summary.minimum}–${data.retrospective.fit_target_passes_summary.maximum}</strong>related saved-fit range</div><div class="mel__metric"><strong>${number(ref.random_expected_passes, 2)}</strong>exact passes expected for random fifty</div><div class="mel__metric"><strong>${number(selectedRecord.measurement_summary.LogD, 2)}</strong>measured LogD for inspected ${esc(selected)}</div></div>${randomBand(summary)}<p class="mel__muted">Shaded band: 95% of 2,000 seeded random-shortlist pass counts (${ref.random_low_95.toFixed(0)}–${ref.random_high_95.toFixed(0)}). Blue line: analytic expectation. Teal line: this committed shortlist. Related repeat/fold fits are selection sensitivity views, not independent trials.</p>` : `<p class="mel__muted">${esc(sourceLabel(state))}: 50 ordered IDs. Target: LogD ${data.targets.logd_low}–${data.targets.logd_high}, KSOL ≥${data.targets.ksol_min_um} µM. Outcomes remain hidden.</p>`}
          <div class="mel__question"><strong>${measured ? "Two properties are not the whole profile. What important question remains?" : "Predictions placed these molecules in the target region. Did the measurements agree?"}</strong><span>${measured ? "Next, inspect permeability and efflux for the unchanged fifty." : "Reveal the recorded LogD and solubility without changing the committed IDs."}</span></div>
          <div class="mel__action-row">${measured ? `<button type="button" class="mel__action" data-primary="true" data-action="caco">Ask about permeability and efflux</button>` : `<button type="button" class="mel__action" data-primary="true" data-action="measure">Compare with measurements</button>`}</div>
        </div>
        <div data-card-host>${evidenceCard(selected, state)}</div>
      </div>`;
    }

    function cacoPlot(state) {
      const ids = committedIds(state);
      const paired = ids.filter((id) => records[id].endpoints[4].value != null && records[id].endpoints[5].value != null);
      const papp = paired.map((id) => records[id].endpoints[4].value);
      const efflux = paired.map((id) => records[id].endpoints[5].value);
      const box = {w:720,h:390,left:64,right:22,top:22,bottom:54};
      const xMin = 0, xMax = Math.ceil(Math.max(...papp) / 5) * 5;
      const yMin = 0, yMax = Math.ceil(Math.max(...efflux));
      const x = (value) => box.left + (value - xMin) / (xMax - xMin) * (box.w - box.left - box.right);
      const y = (value) => box.top + (yMax - value) / (yMax - yMin) * (box.h - box.top - box.bottom);
      const ticks = [0,.25,.5,.75,1];
      const points = paired.map((id) => {
        const record = records[id];
        const pass = record.measurement_summary.target_pass;
        return `<circle class="point" data-caco-id="${esc(id)}" data-measured="true" data-pass="${pass}" data-selected="${id === state.inspected_molecule_id}" cx="${x(record.endpoints[4].value)}" cy="${y(record.endpoints[5].value)}" r="${id === state.inspected_molecule_id ? 7 : 5}" role="button" aria-label="Inspect ${esc(id)}: Papp ${number(record.endpoints[4].value, 2)}, efflux ${number(record.endpoints[5].value, 2)}"></circle>`;
      }).join("");
      return `<svg class="mel__plot" data-testid="caco-plane" viewBox="0 0 ${box.w} ${box.h}" role="img" aria-label="Caco-2 Papp and efflux measurements for ${paired.length} of the unchanged committed fifty">
        ${ticks.map((fraction) => `<line class="axis" x1="${x(fraction*xMax)}" y1="${box.top}" x2="${x(fraction*xMax)}" y2="${box.h-box.bottom}"></line><text class="tick" x="${x(fraction*xMax)}" y="${box.h-box.bottom+18}" text-anchor="middle">${number(fraction*xMax,0)}</text><line class="axis" x1="${box.left}" y1="${y(fraction*yMax)}" x2="${box.w-box.right}" y2="${y(fraction*yMax)}"></line><text class="tick" x="${box.left-9}" y="${y(fraction*yMax)+4}" text-anchor="end">${number(fraction*yMax,1)}</text>`).join("")}
        <text class="axis-label" x="${(box.left+box.w-box.right)/2}" y="${box.h-13}" text-anchor="middle">Measured Caco-2 Papp A&gt;B (10^-6 cm/s)</text>
        <text class="axis-label" transform="translate(16 ${(box.top+box.h-box.bottom)/2}) rotate(-90)" text-anchor="middle">Measured Caco-2 efflux ratio</text>${points}
      </svg>`;
    }

    function cacoMarkup(state) {
      const ids = committedIds(state);
      const paired = ids.filter((id) => records[id].endpoints[4].status === "measured" && records[id].endpoints[5].status === "measured" && records[id].endpoints[4].value != null && records[id].endpoints[5].value != null);
      const initialPasses = shortlistSummary(ids).passes;
      const pairedPasses = paired.filter((id) => records[id].measurement_summary.target_pass).length;
      const misses = paired.filter((id) => !records[id].measurement_summary.target_pass).sort();
      const contrast = (misses.length ? misses : [...paired].sort())[0] || null;
      return `<div class="mel__instrument">
        <div class="mel__panel mel__viewport">
          <div class="mel__toolbar"><div><p class="mel__eyebrow">A separate assay question</p><h3>The first result remains visible; Caco-2 adds permeability and efflux.</h3><p class="mel__muted">Papp asks how readily a molecule crosses a cell-like layer. The efflux ratio asks whether transport proteins appear to pump more material back in the opposite direction.</p></div><div class="mel__badge">${esc(sourceLabel(state))} · ${initialPasses}/50 initial passes</div></div>
          ${cacoPlot(state)}
          ${trayMarkup(ids, state, "caco")}
          <div class="mel__result"><div class="mel__metric"><strong>${paired.length}/50</strong>paired numeric Caco-2 evidence</div><div class="mel__metric"><strong>${pairedPasses}/${initialPasses}</strong>initial passes with paired Caco-2</div><div class="mel__metric"><strong>${50 - paired.length}</strong>missing or bounded Caco-2 evidence</div></div>
          <p class="mel__muted">Hatched tray slots are missing or bounded for at least one Caco-2 measure; they are selectable and are not counted as failures.${contrast ? ` Optional deterministic contrast: <button type="button" class="mel__action" data-inspect-example="${esc(contrast)}">paired target-miss contrast ${esc(contrast)}</button>.` : ""}</p>
          <div class="mel__question"><strong>What should this teach us about an unmeasured proposal?</strong><span>Return to the structure you retained. Its assay slots will still be empty; the retrospective evidence can guide the next question, not answer it.</span></div>
          <div class="mel__action-row"><button type="button" class="mel__action" data-primary="true" data-action="return">Apply the lesson to my proposal</button><button type="button" class="mel__action" data-action="restart">Choose another shortlist</button></div>
        </div>
        <div data-card-host>${evidenceCard(committedInspection(state), state)}</div>
      </div>`;
    }

    const assayReasons = {
      "Caco-2 permeability and efflux": "Could reveal transport behavior that the original LogD/KSOL question cannot answer.",
      "Kinetic solubility": "Would replace a computed context cue with a measurement for this exact proposal.",
      "HLM intrinsic clearance": "Would add a human-microsomal metabolism question omitted by the original objective.",
    };

    function returnMarkup(state) {
      const candidate = records[state.candidate_id];
      if (!candidate) return `<div class="mel__panel"><p>The retained candidate is missing. Choose a proposal again.</p></div>`;
      const hopeIds = committedIds(state).filter((id) => records[id].measurement_summary.target_pass).filter((id) => {
        const endpoints = records[id].endpoints;
        return endpoints[4].status === "measured" && endpoints[5].status === "measured";
      }).sort().slice(0, 2);
      const hope = hopeIds.map((id) => {
        const record = records[id];
        return `<div class="mel__hope-card"><div class="mel__structure">${depiction(id)}</div><strong>${esc(id)}</strong><p class="mel__muted">Measured LogD ${number(record.measurement_summary.LogD,2)} · KSOL ${number(record.measurement_summary.KSOL_uM,1)} µM. Example rule: measured target pass with broader-profile evidence; not a clinical claim.</p></div>`;
      }).join("");
      const assays = Object.keys(assayReasons).map((assay) => `<button type="button" class="mel__assay" data-assay="${esc(assay)}" aria-pressed="${state.next_assay === assay}"><strong>${esc(assay)}</strong><span class="mel__muted">${esc(assayReasons[assay])}</span></button>`).join("");
      return `<div class="mel__return">
        <div>${evidenceCard(candidate.molecule_id, state)}<div class="mel__panel" style="margin-top:12px"><p class="mel__eyebrow">Choose the next unanswered question</p><p class="mel__muted">Each option names evidence that could change how this exact proposal is judged. Choosing does not commission an assay or fabricate a result.</p><div class="mel__assays">${assays}</div>${state.next_assay ? `<div class="mel__decision" aria-live="polite"><strong>${esc(candidate.molecule_id)}</strong> · next question: ${esc(state.next_assay)}. ${esc(assayReasons[state.next_assay])} No assay is commissioned and no result is fabricated.</div>` : ""}<div class="mel__action-row"><button type="button" class="mel__action" data-action="restart">Choose another shortlist</button></div></div></div>
        <div class="mel__panel"><p class="mel__eyebrow">Measured reasons for hope</p><h3>Useful enrichment survived the surprise.</h3><p class="mel__muted">These are lexicographically first eligible initial passes from the committed ${esc(sourceLabel(state)).toLowerCase()}. Their measurements never transfer to ${esc(candidate.molecule_id)}.</p><div class="mel__hope">${hope}</div></div>
      </div>`;
    }

    function bindSelection(state) {
      root.querySelectorAll("[data-seed-id]").forEach((button) => button.addEventListener("click", () => {
        setState({seed_id: button.dataset.seedId, candidate_id: null, returned_to_proposal: false, next_assay: null});
      }));
      root.querySelectorAll("[data-candidate-id]").forEach((button) => button.addEventListener("click", () => {
        setState({candidate_id: button.dataset.candidateId, returned_to_proposal: false, next_assay: null});
      }));
    }

    function bindInspection() {
      root.querySelectorAll("[data-union-id], [data-tray-id], [data-point-id], [data-caco-id], [data-inspect-example]").forEach((element) => {
        const activate = () => {
          const id = element.dataset.unionId || element.dataset.trayId || element.dataset.pointId || element.dataset.cacoId || element.dataset.inspectExample;
          setState({inspected_molecule_id: id, inspected_by_visitor: true});
        };
        element.addEventListener("click", activate);
        if (element.tagName.toLowerCase() === "circle") {
          element.setAttribute("tabindex", "0");
          element.addEventListener("keydown", (event) => {
            if (event.key === "Enter" || event.key === " ") { event.preventDefault(); activate(); }
          });
        }
      });
    }

    function updateFitLocal(index) {
      const fitKey = nominations.fit_keys[index];
      const active = new Set(nominations.nominations[fitKey]);
      const label = root.querySelector("[data-fit-label]");
      const overlap = root.querySelector("[data-overlap]");
      if (label) label.textContent = nominations.fit_metadata[index].label;
      if (overlap) overlap.textContent = nominations.fit_to_ensemble_overlap[fitKey];
      root.querySelectorAll("[data-union-id]").forEach((cell) => {
        const nominated = active.has(cell.dataset.unionId);
        cell.dataset.nominated = String(nominated);
        cell.setAttribute("aria-label", `${cell.dataset.unionId}; nominated in ${nominations.inclusion_counts[cell.dataset.unionId]} of 25 fits; ${nominated ? "selected by active fit" : "not selected by active fit"}`);
      });
      const tray = root.querySelector(".mel__tray");
      if (tray) tray.outerHTML = trayMarkup(nominations.nominations[fitKey], {...getState(), active_fit_index:index, active_fit_key:fitKey}, "prediction");
      const host = root.querySelector("[data-card-host]");
      const current = getState();
      const inspected = current.inspected_by_visitor ? current.inspected_molecule_id : data.retrospective.unanimous_id;
      if (host) host.innerHTML = evidenceCard(inspected, {...current, active_fit_index:index, active_fit_key:fitKey, inspected_molecule_id:inspected}, fitKey);
      root.querySelectorAll("[data-tray-id]").forEach((element) => element.addEventListener("click", () => setState({inspected_molecule_id:element.dataset.trayId})));
    }

    function bindNomination(state) {
      const slider = root.querySelector('[data-testid="fit-scrubber"]');
      if (slider) {
        slider.addEventListener("input", () => {
          const index = Number(slider.value);
          updateFitLocal(index);
          window.clearTimeout(fitDebounce);
          fitDebounce = window.setTimeout(() => setState({active_fit_index:index, active_fit_key:nominations.fit_keys[index], inspected_molecule_id:getState().inspected_by_visitor ? getState().inspected_molecule_id : data.retrospective.unanimous_id, fit_explored:true}), 180);
        });
        slider.addEventListener("change", () => {
          window.clearTimeout(fitDebounce);
          const index = Number(slider.value);
          setState({active_fit_index:index, active_fit_key:nominations.fit_keys[index], inspected_molecule_id:getState().inspected_by_visitor ? getState().inspected_molecule_id : data.retrospective.unanimous_id, fit_explored:true});
        });
      }
      const commit = (kind) => {
        const current = getState();
        const fitKey = nominations.fit_keys[Number(current.active_fit_index || 0)];
        const ids = kind === "active_fit" ? nominations.nominations[fitKey] : nominations.ensemble_ids;
        const inspected = ids.includes(current.inspected_molecule_id) ? current.inspected_molecule_id : ids[0];
        setState({selection_kind:kind, committed_fit_key:kind === "active_fit" ? fitKey : null, committed_ids:[...ids], evidence_stage:"prediction", inspected_molecule_id:inspected, selection_notice: inspected === current.inspected_molecule_id ? null : `The inspected molecule was outside this shortlist; ${inspected} is its deterministic first-slot fallback.`});
      };
      const fitCommit = root.querySelector('[data-action="commit-fit"]');
      if (fitCommit) fitCommit.addEventListener("click", () => commit("active_fit"));
      const ensembleCommit = root.querySelector('[data-action="commit-ensemble"]');
      if (ensembleCommit) ensembleCommit.addEventListener("click", () => commit("ensemble"));
      const unanimous = root.querySelector('[data-action="focus-unanimous"]');
      if (unanimous) unanimous.addEventListener("click", () => setState({inspected_molecule_id:data.retrospective.unanimous_id, inspected_by_visitor:false}));
    }

    function animateMeasurement(force = false) {
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches && !force) return;
      const svg = root.querySelector('[data-testid="property-plane"]');
      if (!svg || getState().evidence_stage !== "measured") return;
      const geometry = plotGeometry(committedIds(getState()));
      const start = performance.now();
      const duration = 850;
      const tick = (now) => {
        const t = clamp((now - start) / duration, 0, 1);
        const eased = 1 - Math.pow(1 - t, 3);
        svg.querySelectorAll("[data-point-id]").forEach((circle) => {
          const record = records[circle.dataset.pointId];
          const px = record.ensemble_prediction.LogD + (record.measurement_summary.LogD - record.ensemble_prediction.LogD) * eased;
          const pyLog = Math.log10(record.ensemble_prediction.KSOL_uM) + (Math.log10(record.measurement_summary.KSOL_uM) - Math.log10(record.ensemble_prediction.KSOL_uM)) * eased;
          circle.setAttribute("cx", geometry.x(px));
          circle.setAttribute("cy", geometry.y(Math.pow(10, pyLog)));
        });
        if (t < 1) animationFrame = requestAnimationFrame(tick);
      };
      animationFrame = requestAnimationFrame(tick);
    }

    function bindOutcome(state, shouldAnimate) {
      const measure = root.querySelector('[data-action="measure"]');
      if (measure) measure.addEventListener("click", () => setState({evidence_stage:"measured", measurements_revealed:true, inspected_molecule_id:data.retrospective.unanimous_id}));
      const replay = root.querySelector('[data-action="replay"]');
      if (replay) replay.addEventListener("click", () => animateMeasurement(true));
      const caco = root.querySelector('[data-action="caco"]');
      if (caco) caco.addEventListener("click", () => setState({evidence_stage:"caco", caco_revealed:true}));
      if (shouldAnimate) animateMeasurement(false);
    }

    function bindCaco() {
      const back = root.querySelector('[data-action="return"]');
      if (back) back.addEventListener("click", () => {
        const state = getState();
        setState({returned_to_proposal:true, evidence_stage:"returned", inspected_molecule_id:state.candidate_id});
      });
      bindRestart();
    }

    function bindReturn() {
      root.querySelectorAll("[data-assay]").forEach((button) => button.addEventListener("click", () => setState({next_assay:button.dataset.assay})));
      bindRestart();
    }

    function bindRestart() {
      const restart = root.querySelector('[data-action="restart"]');
      if (restart) restart.addEventListener("click", () => setState({
        active_fit_index: 0,
        active_fit_key: nominations.fit_keys[0],
        inspected_molecule_id: data.retrospective.unanimous_id,
        inspected_by_visitor: false,
        selection_kind: null,
        committed_fit_key: null,
        committed_ids: [],
        evidence_stage: "nomination",
        measurements_revealed: false,
        caco_revealed: false,
        returned_to_proposal: false,
        next_assay: null,
        fit_explored: false,
      }));
    }

    function draw() {
      if (animationFrame !== null) cancelAnimationFrame(animationFrame);
      const state = getState();
      const shouldAnimate = previousStage !== "measured" && state.evidence_stage === "measured";
      previousStage = state.evidence_stage;
      let body = "";
      if (!state.candidate_id) {
        body = selectionMarkup(state) + retainedMarkup(state) + `<div class="mel__transition"><p class="mel__eyebrow">What happens after this choice?</p><p>Selecting a proposal gives the story one unmeasured structure to return to. The next scene deliberately sets it aside and examines a separate held-out collection where both predictions and measurements already exist.</p></div>`;
      } else if (state.returned_to_proposal) {
        body = retainedMarkup(state) + returnMarkup(state);
      } else if (state.caco_revealed) {
        body = selectionShell(state) + retainedMarkup(state) + cacoMarkup(state);
      } else if (state.selection_kind) {
        body = selectionShell(state) + retainedMarkup(state) + outcomeMarkup(state);
      } else {
        body = selectionShell(state) + retainedMarkup(state) + `<div class="mel__transition"><p class="mel__eyebrow">A separate retrospective test</p><h3>Now set the proposal aside and examine decisions we can check.</h3><p>The generated proposal does not enter this analysis. We use 2,160 held-out ExpansionRx molecules with saved model predictions and recorded LogD and kinetic-solubility measurements. Each model fit gets the same illustrative budget: recommend fifty.</p></div>` + nominationMarkup(state);
      }
      const header = storyHeader(state);
      root.innerHTML = `<div class="mel__header"><div><p class="mel__eyebrow">${esc(header.eyebrow)}</p><h2>${esc(header.title)}</h2><p class="mel__muted mel__lede">${esc(header.lede)}</p></div><div class="mel__progress" aria-label="Story progress: ${stageIndex(state)} of 9 milestones">${progress(state)}</div></div>${body}`;
      bindSelection(state);
      bindInspection();
      if (state.candidate_id && !state.returned_to_proposal && !state.caco_revealed && !state.selection_kind) bindNomination(state);
      if (state.selection_kind && !state.caco_revealed && !state.returned_to_proposal) bindOutcome(state, shouldAnimate);
      if (state.caco_revealed && !state.returned_to_proposal) bindCaco();
      if (state.returned_to_proposal) bindReturn();
    }

    draw();
    const onState = () => draw();
    model.on("change:state", onState);
    return () => {
      if (animationFrame !== null) cancelAnimationFrame(animationFrame);
      if (fitDebounce !== null) window.clearTimeout(fitDebounce);
      model.off("change:state", onState);
    };
  },
};

widget_assets.lens_css:
.mel {
  --ink: #17212b;
  --muted: #5d6a73;
  --paper: #f7f4ee;
  --panel: #fffdfa;
  --line: #d9d3c8;
  --aqua: #167d78;
  --aqua-soft: #d9efeb;
  --blue: #335c81;
  --blue-soft: #dfeaf3;
  --gold: #d79b2b;
  --gold-soft: #f8ebc9;
  --plum: #774a70;
  --missing: #ebe7df;
  color: var(--ink);
  font-family: "PT Sans", sans-serif;
  background: var(--paper);
  border-radius: 24px;
  padding: clamp(16px, 3vw, 30px);
}
.mel * { box-sizing: border-box; }
.mel h2, .mel h3, .mel p { margin-top: 0; }
.mel h2 { margin-bottom: 5px; font: 600 clamp(25px, 4vw, 43px)/1.08 "Lora", serif; letter-spacing: -.025em; }
.mel h3 { margin-bottom: 8px; font: 600 21px/1.2 "Lora", serif; }
.mel__eyebrow { margin: 0 0 6px; color: var(--aqua); font-size: 12px; font-weight: 750; letter-spacing: .13em; text-transform: uppercase; }
.mel__muted { color: var(--muted); font-size: 13px; line-height: 1.5; }
.mel__lede { max-width: 850px; margin-bottom: 0; font-size: 15px; }
.mel__header { display: flex; justify-content: space-between; gap: 20px; align-items: end; flex-wrap: wrap; margin-bottom: 18px; }
.mel__progress { display: flex; gap: 4px; align-items: center; }
.mel__progress span { width: 17px; height: 5px; border-radius: 5px; background: var(--line); }
.mel__progress span[data-done="true"] { background: var(--aqua); }
.mel__panel { background: var(--panel); border: 1px solid var(--line); border-radius: 18px; padding: clamp(14px, 2.2vw, 23px); }
.mel__transition { margin: 0 0 14px; padding: clamp(14px, 2vw, 20px); border-left: 4px solid var(--aqua); border-radius: 0 14px 14px 0; background: var(--aqua-soft); }
.mel__transition h3 { margin-bottom: 6px; }
.mel__transition p:last-child { max-width: 920px; margin-bottom: 0; color: var(--muted); font-size: 14px; line-height: 1.55; }
.mel__selection { display: grid; grid-template-columns: .8fr 1.2fr; gap: 18px; margin-bottom: 14px; }
.mel__cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(135px, 1fr)); gap: 9px; }
.mel button { font: inherit; color: inherit; }
.mel__choice, .mel__action, .mel__assay { appearance: none; border: 1px solid var(--line); background: var(--panel); border-radius: 12px; min-height: 44px; text-align: left; }
.mel__choice { padding: 8px; display: grid; grid-template-rows: 88px auto; gap: 6px; }
.mel__choice:hover, .mel__assay:hover { border-color: var(--aqua); }
.mel button:focus-visible, .mel input:focus-visible, .mel summary:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.mel__choice[aria-pressed="true"] { border: 2px solid var(--aqua); background: var(--aqua-soft); }
.mel__choice-image { background: white; border-radius: 8px; display: grid; place-items: center; overflow: hidden; }
.mel__choice-image svg { width: 100%; height: 88px; }
.mel__choice strong { display: block; font-size: 13px; }
.mel__choice small { color: var(--muted); font-size: 11px; }
.mel__extra { margin-top: 10px; }
.mel__extra summary { color: var(--blue); font-weight: 700; }
.mel__extra .mel__cards { margin-top: 10px; }
.mel__retained { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin: 14px 0; padding: 10px 14px; border-radius: 14px; color: #fff; background: var(--ink); }
.mel__retained strong { font-family: "PT Sans", sans-serif; }
.mel__change { margin-bottom: 10px; }
.mel__change > summary { color: var(--blue); font-weight: 700; }
.mel__change .mel__selection { margin-top: 10px; }
.mel__retained span:last-child { color: #cfe3e1; font-size: 12px; text-align: right; }
.mel__instrument { display: grid; grid-template-columns: minmax(0, 1.48fr) minmax(275px, .72fr); gap: 14px; }
.mel__viewport { min-width: 0; }
.mel__toolbar { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin-bottom: 12px; flex-wrap: wrap; }
.mel__fit { flex: 1; min-width: 250px; }
.mel__fit-label { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 5px; }
.mel__fit-label strong { font-size: 14px; }
.mel__fit-label span { color: var(--muted); font-size: 12px; }
.mel__fit input { width: 100%; accent-color: var(--aqua); }
.mel__stats { display: flex; gap: 15px; flex-wrap: wrap; color: var(--muted); font-size: 12px; }
.mel__stats strong { color: var(--ink); font-size: 17px; }
.mel__matrix { display: grid; grid-template-columns: repeat(32, 1fr); gap: 3px; padding: 8px 0 12px; }
.mel__cell { appearance: none; border: 0; min-width: 0; aspect-ratio: 1; padding: 0; border-radius: 3px; background: var(--missing); opacity: .72; }
.mel__cell[data-nominated="true"] { background: var(--blue); opacity: .95; }
.mel__cell[data-unanimous="true"] { box-shadow: inset 0 0 0 2px var(--gold), 0 0 0 1px var(--ink); }
.mel__cell[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--panel), 0 0 0 2px var(--plum); }
.mel__legend { display: flex; align-items: center; gap: 13px; flex-wrap: wrap; color: var(--muted); font-size: 11px; }
.mel__swatch { display: inline-block; width: 11px; height: 11px; border-radius: 3px; vertical-align: -2px; margin-right: 4px; background: var(--missing); }
.mel__swatch--selected { background: var(--blue); }
.mel__swatch--unanimous { background: var(--blue); box-shadow: inset 0 0 0 2px var(--gold); }
.mel__card { min-width: 0; }
.mel__structure { min-height: 185px; display: grid; place-items: center; background: #fff; border-radius: 13px; overflow: hidden; }
.mel__structure svg { width: 100%; height: auto; max-height: 210px; }
.mel__identity { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; margin: 12px 0 7px; }
.mel__identity strong { font: 700 16px/1 "PT Sans", sans-serif; }
.mel__badge { display: inline-flex; align-items: center; min-height: 24px; padding: 3px 8px; border-radius: 999px; background: var(--blue-soft); color: var(--blue); font-size: 11px; font-weight: 750; }
.mel__strip { display: grid; grid-template-columns: repeat(9, minmax(20px, 1fr)); gap: 4px; margin: 11px 0; }
.mel__slot { aspect-ratio: 1; border: 1px solid var(--line); border-radius: 6px; display: grid; place-items: center; background: var(--missing); color: var(--muted); font-size: 8px; font-weight: 800; }
.mel__slot[data-status="predicted"] { background: var(--blue-soft); border-color: var(--blue); color: var(--blue); }
.mel__slot[data-status="measured"] { background: var(--aqua-soft); border-color: var(--aqua); color: var(--aqua); }
.mel__slot[data-status="bounded"] { background: repeating-linear-gradient(135deg, var(--gold-soft), var(--gold-soft) 4px, var(--panel) 4px, var(--panel) 8px); border-color: var(--gold); color: var(--ink); }
.mel__slot[data-status="hidden"] { background: var(--panel); border-style: dashed; }
.mel__values { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 12px; color: var(--muted); font-size: 12px; }
.mel__values strong { display: block; color: var(--ink); font-size: 14px; }
.mel__tray { display: grid; grid-template-columns: repeat(25, 1fr); gap: 3px; margin: 14px 0 5px; }
.mel__tray button { appearance: none; border: 0; padding: 0; aspect-ratio: 1; border-radius: 2px; background: var(--blue); opacity: .9; min-width: 0; }
.mel__tray button[data-pass="true"] { background: var(--aqua); }
.mel__tray button[data-missing="true"] { background: repeating-linear-gradient(135deg, var(--missing), var(--missing) 3px, var(--panel) 3px, var(--panel) 6px); box-shadow: inset 0 0 0 1px var(--line); }
.mel__tray button[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--plum); }
.mel__action-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 14px; }
.mel__question { display: grid; gap: 3px; margin-top: 16px; padding: 12px 14px; border-left: 4px solid var(--gold); background: var(--gold-soft); color: var(--muted); font-size: 13px; line-height: 1.45; }
.mel__question strong { color: var(--ink); font-size: 14px; }
.mel__action { padding: 10px 15px; font-weight: 750; text-align: center; }
.mel__action[data-primary="true"] { border-color: var(--ink); color: #fff; background: var(--ink); }
.mel__action:disabled { opacity: .45; }
.mel__plot { width: 100%; min-height: 390px; background: var(--panel); border-radius: 12px; }
.mel__plot .axis { stroke: var(--line); stroke-width: 1; }
.mel__plot .tick { fill: var(--muted); font-size: 11px; }
.mel__plot .axis-label { fill: var(--ink); font-size: 12px; font-weight: 700; }
.mel__plot .target { fill: var(--aqua-soft); opacity: .75; }
.mel__plot .point { fill: var(--panel); stroke: var(--blue); stroke-width: 2; }
.mel__plot .point[data-measured="true"] { fill: var(--aqua); stroke: var(--ink); }
.mel__plot .point[data-selected="true"] { stroke: var(--plum); stroke-width: 4; }
.mel__plot .point[data-pass="false"] { fill: var(--gold-soft); stroke: var(--gold); }
.mel__plot .connector { stroke: var(--plum); stroke-width: 2; stroke-dasharray: 4 4; }
.mel__result { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 10px; }
.mel__metric { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 10px 12px; color: var(--muted); font-size: 12px; }
.mel__metric strong { display: block; color: var(--ink); font: 600 24px/1.1 "Lora", serif; }
.mel__random { width: 100%; height: 52px; }
.mel__random .band { fill: var(--blue-soft); }
.mel__random .expected { stroke: var(--blue); stroke-width: 2; }
.mel__random .observed { stroke: var(--aqua); stroke-width: 4; }
.mel__random text { fill: var(--muted); font-size: 10px; }
.mel__return { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.mel__hope { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.mel__hope-card { background: var(--panel); border: 1px solid var(--line); border-radius: 13px; padding: 8px; }
.mel__hope-card .mel__structure { min-height: 115px; }
.mel__hope-card .mel__structure svg { max-height: 125px; }
.mel__assays { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 12px; }
.mel__assay { padding: 12px; }
.mel__assay[aria-pressed="true"] { border: 2px solid var(--aqua); background: var(--aqua-soft); }
.mel__assay strong { display: block; margin-bottom: 4px; }
.mel__decision { margin-top: 12px; padding: 12px; border-left: 4px solid var(--aqua); background: var(--aqua-soft); }
.mel__decision strong { font-family: "PT Sans", sans-serif; }
@media (max-width: 900px) {
  .mel__selection, .mel__instrument, .mel__return { grid-template-columns: 1fr; }
  .mel__matrix { grid-template-columns: repeat(24, 1fr); }
}
@media (max-width: 560px) {
  .mel__matrix { grid-template-columns: repeat(16, 1fr); gap: 4px; }
  .mel__tray { grid-template-columns: repeat(10, 1fr); gap: 4px; }
  .mel__result, .mel__assays { grid-template-columns: 1fr; }
  .mel__selection { gap: 12px; }
}
@media (prefers-reduced-motion: reduce) {
  .mel * { scroll-behavior: auto !important; }
}

widget_assets.scale_js:
function esc(value) {
  return String(value ?? "").replace(/[&<>'"]/g, (char) => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[char]);
}

function formatCount(value) {
  return new Intl.NumberFormat("en-US").format(value);
}

async function unpackSvg(encoded) {
  const binary = atob(encoded);
  const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream).text();
}

export default {
  async render({ model, el }) {
    const root = document.createElement("section");
    root.className = "bymi-scale";
    root.dataset.testid = "scale-journey";
    el.replaceChildren(root);
    let timer = null;
    let level = 0;

    const rawPayload = model.get("payload");
    const resolvedPayload = {...rawPayload, seed_svg: await unpackSvg(rawPayload.seed_svg_gzip_base64)};
    const payload = () => resolvedPayload;
    const state = () => model.get("state") || {};
    const sync = (patch) => {
      const next = {...state(), ...patch, event_sequence: (state().event_sequence || 0) + 1};
      model.set("state", next);
      model.save_changes();
    };
    const stop = () => {
      if (timer !== null) window.clearInterval(timer);
      timer = null;
    };
    const showLevel = (nextLevel) => {
      level = Math.max(0, Math.min(nextLevel, payload().scale_landmarks.length));
      draw();
      if (level === payload().scale_landmarks.length) {
        stop();
        sync({complete: true});
      }
    };
    const begin = (reduced = false) => {
      stop();
      const motionReduced = reduced || window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      sync({started: true, complete: motionReduced, reduced_motion: motionReduced});
      if (motionReduced) {
        showLevel(payload().scale_landmarks.length);
        return;
      }
      showLevel(0);
      timer = window.setInterval(() => showLevel(level + 1), 1800);
    };

    function scaleMarkup() {
      const landmarks = payload().scale_landmarks;
      const item = landmarks[Math.min(level, landmarks.length - 1)];
      const cellCount = level === 0 ? 1 : 100;
      const cells = Array.from({length: cellCount}, (_, index) => {
        const visible = index < item.marks;
        return `<span class="bymi-scale__cell" data-empty="${!visible}"${level === 0 ? ' style="width:70px;height:70px;border-radius:12px"' : ""}></span>`;
      }).join("");
      const perMark = item.count / item.marks;
      const zoom = [1, 1.38, 1.12, .92, .75][Math.min(level, 4)];
      const gridStyle = level === 0 ? "grid-template-columns:70px;gap:0" : `transform:scale(${zoom})`;
      const source = level === 4
        ? "GDB-17 is a bounded enumeration—not every possible drug-like molecule. It covers molecules with at most 17 non-hydrogen atoms drawn from a specified set of elements."
        : "At each step, one square stands for a larger counted group. The squares preserve continuity; they are not individual molecular drawings.";
      return `
        <div class="bymi-scale__question"><strong>What are you looking at?</strong> A single possibility is repeatedly grouped into larger collections so the scale remains countable as we pull back.</div>
        <div class="bymi-scale__count">
          <span class="bymi-scale__number">${formatCount(item.count)}</span>
          <span class="bymi-scale__unit">${esc(item.label)}</span>
        </div>
        <div class="bymi-scale__field" aria-label="${formatCount(item.count)} schematic possibilities">
          <div class="bymi-scale__grid" style="${gridStyle}">${cells}</div>
        </div>
        <div class="bymi-scale__caption">
          <p><strong>One square now represents ${formatCount(perMark)} ${perMark === 1 ? "possibility" : "possibilities"}.</strong> ${source} Schematic logarithmic compression; the marks are aggregates, not rendered molecules.</p>
          <div class="bymi-scale__steps" aria-label="Scale level ${Math.min(level + 1, 5)} of 5">${landmarks.map((_, i) => `<span class="bymi-scale__step" data-active="${i <= level}"></span>`).join("")}</div>
        </div>
        <div class="bymi-scale__landmarks" aria-label="Scale landmarks">${landmarks.map((landmark, index) => `<span data-current="${index === Math.min(level, landmarks.length - 1)}"><strong>${formatCount(landmark.count)}</strong>${esc(landmark.label.replace(/^GDB-17:\s*/i, ""))}</span>`).join("")}</div>`;
    }

    function evidenceMarkup() {
      const data = payload();
      const seed = data.seed;
      const accounting = data.assay_accounting;
      const record = data.seed_record;
      const slots = record.endpoints.map((endpoint) => `<span class="bymi-scale__slot" data-filled="${endpoint.status === "measured"}" aria-label="${esc(endpoint.label)}: ${esc(endpoint.status)}" title="${esc(endpoint.label)}">${esc(endpoint.short_label)}</span>`).join("");
      const coverage = accounting.endpoint_columns.map((endpoint, index) => {
        const height = 100 * accounting.per_endpoint[endpoint] / accounting.records;
        return `<div><div class="bymi-scale__coverage-col" aria-label="${esc(endpoint)}: ${accounting.per_endpoint[endpoint]} numeric records"><span class="bymi-scale__coverage-fill" style="height:${height.toFixed(1)}%"></span></div><span class="bymi-scale__unit">${esc(record.endpoints[index].short_label)}</span></div>`;
      }).join("");
      const finalLandmark = data.scale_landmarks[data.scale_landmarks.length - 1];
      return `<div class="bymi-scale__recap" data-testid="scale-summary">
        <p class="bymi-scale__eyebrow">Why a shortlist is necessary</p>
        <h3>One per second would still take about ${formatCount(Math.round(finalLandmark.hypothetical_years_at_one_per_second))} years.</h3>
        <p>GDB-17 contains about 166 billion enumerated structures within a specific boundary: no more than 17 non-hydrogen atoms from its allowed elements. It is a scale reference, not the ExpansionRx dataset and not a claim about all chemical space. The one-per-second comparison is hypothetical inspection time, not a laboratory throughput estimate.</p>
        <div class="bymi-scale__landmarks" aria-label="Scale landmarks summary">${data.scale_landmarks.map((landmark) => `<span><strong>${formatCount(landmark.count)}</strong>${esc(landmark.label.replace(/^GDB-17:\s*/i, ""))}</span>`).join("")}</div>
      </div>
      <div class="bymi-scale__evidence-intro">
        <p class="bymi-scale__eyebrow">From possibilities to evidence</p>
        <h3>A structure tells us what a molecule is. Measurements tell us how it behaves.</h3>
        <p>This real training molecule has recorded assay results. <strong>LogD</strong> asks how the molecule distributes between water-like and oil-like environments under the assay conditions. <strong>Kinetic solubility</strong> asks how much can dissolve. Other assays ask about metabolism, permeability, efflux, and tissue binding.</p>
      </div>
      <div class="bymi-scale__evidence">
        <div>
          <p class="bymi-scale__eyebrow">One measured molecule</p>
          <div class="bymi-scale__molecule">${data.seed_svg}</div>
        </div>
        <div>
          <h3>${esc(seed.seed_id)} · one ExpansionRx training record</h3>
          <p>Each square below is one possible kind of evidence for this molecule. Filled squares have numeric measurements; empty squares mean the numeric evidence is unavailable here or was recorded only as a bound. Empty never means zero or failure.</p>
          <div class="bymi-scale__strip">${slots}</div>
          <details class="bymi-scale__definitions"><summary>What do the nine assay labels mean?</summary><ul>${record.endpoints.map((endpoint) => `<li><strong>${esc(endpoint.short_label)}</strong> — ${esc(endpoint.label)}</li>`).join("")}</ul></details>
          <p class="bymi-scale__collection-lead"><strong>Now expand from one record to the measured collection.</strong> The bars show how many of the 7,608 released records have a numeric value for each endpoint.</p>
          <div class="bymi-scale__coverage">${coverage}</div>
          <div class="bymi-scale__summary">
            <span><strong>${formatCount(accounting.records)}</strong>released records</span>
            <span><strong>${formatCount(accounting.recorded_values)}</strong>numeric endpoint values</span>
            <span><strong>${formatCount(accounting.missing_or_non_numeric)}</strong>missing or non-numeric slots</span>
          </div>
        </div>
      </div>
      <div class="bymi-scale__caption"><p><strong>Next question:</strong> if experimental evidence is limited, how should a model decide which fifty molecules deserve attention?</p></div>`;
    }

    function draw() {
      const complete = state().complete || level >= payload().scale_landmarks.length;
      root.innerHTML = `
        <div class="bymi-scale__header">
          <div><p class="bymi-scale__eyebrow">Why selection comes first</p><h2>How large is the space behind a shortlist?</h2><p class="bymi-scale__lede">The visual groups possibilities from one to a bounded 166-billion-molecule reference. Watch the grouping, or jump to the complete explanation; both routes end with the same scale landmarks and real measured evidence.</p></div>
          <div class="bymi-scale__controls">
            <button type="button" data-action="pull" data-primary="true">Show the scale</button>
            <button type="button" data-action="skip">Show the summary</button>
          </div>
        </div>
        <div class="bymi-scale__stage" aria-live="polite">${complete ? evidenceMarkup() : scaleMarkup()}</div>`;
      root.querySelector('[data-action="pull"]').addEventListener("click", () => begin(false));
      root.querySelector('[data-action="skip"]').addEventListener("click", () => begin(true));
    }

    draw();
    const onState = () => draw();
    model.on("change:state", onState);
    return () => {
      stop();
      model.off("change:state", onState);
    };
  },
};

widget_assets.scale_css:
.bymi-scale {
  --ink: #17212b;
  --muted: #5d6a73;
  --paper: #f7f4ee;
  --panel: #fffdfa;
  --line: #d9d3c8;
  --aqua: #167d78;
  --aqua-soft: #d9efeb;
  --gold: #d79b2b;
  color: var(--ink);
  font-family: "PT Sans", sans-serif;
  background: var(--paper);
  border-radius: 24px;
  padding: clamp(18px, 3vw, 34px);
  overflow: hidden;
}
.bymi-scale * { box-sizing: border-box; }
.bymi-scale__header { display: flex; align-items: end; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.bymi-scale__eyebrow { margin: 0 0 6px; color: var(--aqua); font-size: 12px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
.bymi-scale h2 { margin: 0; max-width: 760px; font: 600 clamp(25px, 4vw, 48px)/1.05 "Lora", serif; letter-spacing: -.025em; }
.bymi-scale h3 { margin: 0 0 8px; font: 600 clamp(20px, 2.2vw, 27px)/1.18 "Lora", serif; }
.bymi-scale__lede { max-width: 760px; margin: 10px 0 0; color: var(--muted); font-size: 15px; line-height: 1.55; }
.bymi-scale__controls { display: flex; gap: 8px; flex-wrap: wrap; }
.bymi-scale button { appearance: none; border: 1px solid var(--ink); border-radius: 999px; padding: 10px 16px; min-height: 42px; color: var(--ink); background: transparent; font: 650 14px/1 inherit; }
.bymi-scale button:hover { background: var(--panel); }
.bymi-scale button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.bymi-scale button[data-primary="true"] { color: white; background: var(--ink); }
.bymi-scale__stage { position: relative; min-height: 350px; margin-top: 24px; background: var(--panel); border: 1px solid var(--line); border-radius: 18px; padding: clamp(16px, 3vw, 28px); }
.bymi-scale__question { max-width: 760px; margin-bottom: 12px; padding: 10px 12px; border-left: 4px solid var(--aqua); background: var(--aqua-soft); color: var(--muted); font-size: 14px; line-height: 1.45; }
.bymi-scale__question strong { color: var(--ink); }
.bymi-scale__count { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.bymi-scale__number { font: 600 clamp(30px, 6vw, 66px)/1 "Lora", serif; letter-spacing: -.035em; }
.bymi-scale__unit { color: var(--muted); font-size: 13px; }
.bymi-scale__field { min-height: 205px; display: grid; place-items: center; perspective: 900px; overflow: hidden; }
.bymi-scale__grid { display: grid; grid-template-columns: repeat(10, 10px); gap: 4px; padding: 16px; transform-origin: center; transition: transform 650ms cubic-bezier(.2,.8,.2,1); }
.bymi-scale__cell { width: 10px; height: 10px; border-radius: 2px; background: var(--aqua); opacity: .92; }
.bymi-scale__cell[data-empty="true"] { opacity: .1; }
.bymi-scale__caption { display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: end; border-top: 1px solid var(--line); padding-top: 14px; }
.bymi-scale__caption p { margin: 0; max-width: 720px; color: var(--muted); font-size: 14px; line-height: 1.5; }
.bymi-scale__steps { display: flex; gap: 5px; }
.bymi-scale__step { width: 24px; height: 4px; border-radius: 4px; background: var(--line); }
.bymi-scale__step[data-active="true"] { background: var(--aqua); }
.bymi-scale__landmarks { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 7px; margin-top: 16px; }
.bymi-scale__landmarks span { min-height: 58px; padding: 8px; border: 1px solid var(--line); border-radius: 9px; color: var(--muted); font-size: 10px; line-height: 1.25; }
.bymi-scale__landmarks span[data-current="true"] { border-color: var(--aqua); background: var(--aqua-soft); }
.bymi-scale__landmarks strong { display: block; color: var(--ink); font-size: clamp(12px, 1.6vw, 17px); }
.bymi-scale__recap { margin-bottom: 24px; padding-bottom: 20px; border-bottom: 1px solid var(--line); }
.bymi-scale__recap > p:not(.bymi-scale__eyebrow), .bymi-scale__evidence-intro > p:not(.bymi-scale__eyebrow) { max-width: 860px; margin: 0; color: var(--muted); font-size: 14px; line-height: 1.55; }
.bymi-scale__evidence-intro { margin-bottom: 18px; }
.bymi-scale__evidence { display: grid; grid-template-columns: minmax(210px, .72fr) 1.28fr; gap: 22px; align-items: center; min-height: 270px; }
.bymi-scale__molecule { background: #fff; border-radius: 14px; min-height: 190px; display: grid; place-items: center; padding: 10px; }
.bymi-scale__molecule svg { width: 100%; height: auto; max-height: 190px; }
.bymi-scale__strip { display: grid; grid-template-columns: repeat(9, minmax(28px, 1fr)); gap: 6px; margin: 14px 0 22px; }
.bymi-scale__slot { aspect-ratio: 1; display: grid; place-items: center; border-radius: 7px; border: 1px solid var(--line); color: var(--muted); font-size: 9px; font-weight: 700; }
.bymi-scale__slot[data-filled="true"] { background: var(--aqua-soft); border-color: var(--aqua); color: var(--ink); }
.bymi-scale__definitions { margin: -10px 0 18px; color: var(--muted); font-size: 13px; }
.bymi-scale__definitions summary { color: var(--aqua); font-weight: 700; cursor: pointer; }
.bymi-scale__definitions ul { columns: 2; padding-left: 20px; line-height: 1.45; }
.bymi-scale__collection-lead { margin: 0 0 10px; color: var(--muted); font-size: 14px; line-height: 1.45; }
.bymi-scale__coverage { display: grid; grid-template-columns: repeat(9, 1fr); gap: 6px; align-items: end; height: 105px; }
.bymi-scale__coverage > div { height: 100%; display: grid; grid-template-rows: 1fr auto; gap: 4px; }
.bymi-scale__coverage-col { height: 100%; display: flex; align-items: end; background: #ebe7df; border-radius: 5px 5px 2px 2px; overflow: hidden; }
.bymi-scale__coverage-fill { width: 100%; background: var(--aqua); }
.bymi-scale__summary { display: flex; gap: 18px; flex-wrap: wrap; margin-top: 10px; color: var(--muted); font-size: 13px; }
.bymi-scale__summary strong { display: block; color: var(--ink); font: 600 24px/1.2 "Lora", serif; }
@media (max-width: 680px) {
  .bymi-scale__evidence { grid-template-columns: 1fr; }
  .bymi-scale__molecule { min-height: 150px; }
  .bymi-scale__caption { grid-template-columns: 1fr; }
  .bymi-scale__landmarks { grid-template-columns: 1fr 1fr; }
  .bymi-scale__definitions ul { columns: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .bymi-scale__grid { transition: none; }
}
